// Spike: does our Y.Doc shape round-trip cleanly through y-sweet?
// Requires a local y-sweet server: `npx y-sweet@latest serve /tmp/y-sweet-data`
// If the server isn't reachable, the whole suite is skipped so `npm test` stays green.
// Runs in Node env (not happy-dom) because happy-dom enforces CORS on fetch and
// blocks y-sweet's check_store endpoint.

import { describe, it, expect, beforeAll, afterEach, type TestContext } from "vitest"
