const CONNECTION_STRING = "ys://127.0.0.1:8080"

function uniqueDocId(): string {
  return `codex-spike-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`
}

async function serverReachable(): Promise<boolean> {
  // Direct fetch so we own the error handling — the SDK's checkStore prints a noisy
  // error via undici when the server is down, even inside a try/catch.
  const httpUrl = CONNECTION_STRING.replace(/^ys:\/\//, "http://").replace(/^yss:\/\//, "https://")
  const controller = new AbortController()
  const t = setTimeout(() => controller.abort(), 500)
  try {
    const res = await fetch(`${httpUrl}/check_store`, { method: "POST", signal: controller.signal })
    return res.ok
  } catch {
    return false
  } finally {
    clearTimeout(t)
  }
}

async function waitForSync(provider: YSweetProvider, timeoutMs = 3000): Promise<void> {
  if (provider.synced) return
  await new Promise<void>((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("timeout waiting for provider sync")), timeoutMs)
    provider.once("sync", () => { clearTimeout(t); resolve() })
  })
}

function waitForCondition(predicate: () => boolean, timeoutMs = 3000, label = "condition"): Promise<void> {
  return new Promise((resolve, reject) => {
    const start = Date.now()
    const tick = () => {
      if (predicate()) return resolve()
      if (Date.now() - start > timeoutMs) return reject(new Error(`timeout waiting for ${label}`))
      setTimeout(tick, 20)
    }
    tick()
  })
}

