export const authMiddleware = async (
  c: Context<{ Bindings: Env; Variables: Variables }>,
  next: Next
): Promise<Response | void> => {
  // Mock mode for local development - bypass auth entirely
  if (c.env.MOCK_LLM === "true") {
    const mockUser: User = {
      id: 1,
      username: "mock-user",
      email: "mock@localhost",
      password_hash: "",
      gitlab_user_id: undefined,
      gitlab_username: undefined,
      gitlab_token: undefined,
      stripe_customer_id: undefined,
      subscription_tier: "pro" as any,
      preferences: { __auth_source: "mock" },
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };
    c.set("user", mockUser);
    await next();
    return;
  }

  const authHeader = c.req.header("Authorization");

  if (!authHeader) {
    return c.json({ error: "Authorization header required" }, 401);
  }

  const jwtService = new JWTService(c.env);
  const token = jwtService.extractTokenFromHeader(authHeader);

  if (!token) {
    // Help debug client auth header formats without logging credentials.
    const parts = authHeader.trim().split(/\s+/);
    const scheme = parts[0] || "(empty)";
    const segments = parts.length;
    console.warn(
      `[authMiddleware] Unable to extract token from Authorization header (scheme="${scheme}", segments=${segments})`
    );
    return c.json({ error: "Invalid authorization header format" }, 401);
  }

  // Primary path: verify as a Worker-issued JWT and load user from D1.
  const payload = await jwtService.verifyToken(token);
  if (payload) {
    // Check if token is expired
    const now = Math.floor(Date.now() / 1000);
    if (payload.exp < now) {
      return c.json({ error: "Token expired" }, 401);
    }

    // Load user from database
    let user = await jwtService.getUserByUsername(payload.sub);
    if (!user) {
      // Env-based admins (super-admin, ADMIN_USERNAMES) are not in D1.
      // Create a synthetic user so admin tokens work with auth-protected routes.
      const adminCredentials = getAdminCredentials(c.env);
      if (adminCredentials[payload.sub]) {
        user = {
          id: 0,
          username: payload.sub,
          email: `${payload.sub}@admin.local`,
          password_hash: "",
          gitlab_user_id: undefined,
          gitlab_username: undefined,
          gitlab_token: undefined,
          stripe_customer_id: undefined,
          subscription_tier: "pro" as any,
          preferences: { __auth_source: "admin" },
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        };
      } else {
        return c.json({ error: "User not found" }, 401);
      }
    }

    // Store user in context for use in route handlers
    c.set("user", user);
    await next();
    return;
  }

  // Fallback path (important during migration):
  // Tokens minted by Hetzner (FastAPI) may not be verifiable with the Worker SECRET_KEY.
  // In that case, treat the token as opaque and validate it by calling Hetzner /auth/me.
  if (c.env.HETZNER_API_URL) {
    try {
      console.log(
        `[authMiddleware] Falling back to Hetzner /api/v1/auth/me (token starts ${token.slice(
          0,
          12
        )}...)`
      );
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5_000);
      const meResp = await fetch(`${c.env.HETZNER_API_URL}/api/v1/auth/me`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/json",
        },
        signal: controller.signal,
      });
      clearTimeout(timeoutId);

      if (meResp.ok) {
        const me = (await meResp.json()) as {
          id: number;
          username: string;
          email: string;
          gitlab_username?: string;
          preferences?: Record<string, any>;
        };

        // Create a User-shaped object sufficient for LLM routes.
        // NOTE: This user is NOT backed by D1; callers that depend on D1 usage tracking
        // should treat this as "best-effort" until user data is migrated.
        const externalUser: User = {
          id: me.id,
          username: me.username,
          email: me.email,
          password_hash: "",
          gitlab_user_id: undefined,
          gitlab_username: me.gitlab_username,
          gitlab_token: undefined,
          stripe_customer_id: undefined,
          subscription_tier: "free" as any,
          preferences: {
            ...(me.preferences || {}),
            __auth_source: "hetzner",

