export function useCellAudio(
  project: ProjectRecord,
  cell: CodexCell,
): UseCellAudioResult {
  const { session } = useFrontierSession()
  const [state, setState] = useState<UseCellAudioResult["state"]>("idle")
  const [error, setError] = useState<AudioError | null>(null)
  const [isPlaying, setIsPlaying] = useState(false)

  const audioRef = useRef<HTMLAudioElement | null>(null)
  const urlRef = useRef<string | null>(null)

  const selectedAudioId = cell.metadata?.selectedAudioId
  const attachment = selectedAudioId
    ? cell.metadata?.attachments?.[selectedAudioId]
    : undefined
  const attachmentUrl = attachment?.url

  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause()
        audioRef.current = null
      }
      if (urlRef.current) {
        URL.revokeObjectURL(urlRef.current)
        urlRef.current = null
      }
      setState("idle")
      setIsPlaying(false)
      setError(null)
    }
  }, [selectedAudioId])

  const load = useCallback(async (): Promise<Uint8Array> => {
    if (!attachmentUrl) {
      throw { kind: "pointer-missing", message: "No audio attachment on this cell" } as AudioError
    }

    // Web-only (non-git) projects: attachment URL is a frontier-audio:// marker
    // resolved by the R2-backed audio worker.
    const frontier = parseFrontierAudioUrl(attachmentUrl)
    if (frontier) {
      if (!session?.jwt) {
        throw { kind: "no-session", message: "Not signed in" } as AudioError
      }
      try {
        return await fetchCellAudio({
          session,
          projectId: project.id,
          audioId: frontier.audioId,
          ext: frontier.ext,
        })
      } catch (e) {
        throw {
          kind: "download-failed",
          message: e instanceof Error ? e.message : String(e),
        } as AudioError
      }
    }

    if (project.origin?.kind !== "git") {
      throw { kind: "no-git-origin", message: "Project has no git origin" } as AudioError
    }
    if (!session?.gitlabToken) {
      throw { kind: "no-session", message: "Not signed in" } as AudioError
    }

    const repoHandle = await openOpfsRepoDir(
      opfsRepoKey(
        project.origin.gitlabProjectId,
        pathWithNamespaceFromCloneUrl(project.origin.cloneUrl),
      ),
    )
    const repoFs = createOpfsFs(repoHandle)
    let pointerText: string
    try {
      const data = await repoFs.promises.readFile(attachmentUrl, { encoding: "utf8" })
      pointerText = typeof data === "string" ? data : new TextDecoder().decode(data)
    } catch {
      // The codex-editor metadata stores paths as `.project/attachments/files/...`
      // but the git repo may store them under `.project/attachments/pointers/...`.
      // Try the alternate path before giving up.
      const altUrl = attachmentUrl.replace("/attachments/files/", "/attachments/pointers/")
      try {
        const data = await repoFs.promises.readFile(altUrl, { encoding: "utf8" })
        pointerText = typeof data === "string" ? data : new TextDecoder().decode(data)
      } catch (e2) {
        throw {
          kind: "pointer-missing",
          message: `Could not read ${attachmentUrl} (also tried ${altUrl}): ${e2 instanceof Error ? e2.message : String(e2)}`,
        } as AudioError
      }
    }

    const pointer = parsePointerContent(pointerText)
    if (!pointer) {
      throw { kind: "pointer-invalid", message: `${attachmentUrl} is not a valid LFS pointer` } as AudioError
    }

    const cached = await lfsCacheGet(pointer.oid)
    if (cached) return cached

    try {
      const bytes = await downloadLfsBlob({
        cloneUrl: project.origin.cloneUrl,
        gitlabToken: session.gitlabToken,
        oid: pointer.oid,
        size: pointer.size,
      })
      try { await lfsCachePut(pointer.oid, bytes) } catch { /* non-fatal */ }
      return bytes
    } catch (e) {
      if (e && typeof e === "object" && "kind" in e) throw e as AudioError
      throw { kind: "download-failed", message: e instanceof Error ? e.message : String(e) } as AudioError
    }
  }, [attachmentUrl, project, session])

  const play = useCallback(async () => {
    if (audioRef.current) {
      try { await audioRef.current.play() } catch (e) {
        console.error("[useCellAudio] play() rejected", e)
      }
      return
    }
    setState("loading")
    setError(null)
    try {
      const bytes = await load()
      const blob = new Blob([bytes as BlobPart])
      const url = URL.createObjectURL(blob)
      urlRef.current = url
      const audio = new Audio(url)
      audio.onplay = () => setIsPlaying(true)
      audio.onpause = () => setIsPlaying(false)
      audio.onended = () => setIsPlaying(false)
      audioRef.current = audio
      setState("ready")
      try {
        await audio.play()
      } catch (e) {
        console.error("[useCellAudio] play() rejected on fresh audio", e)
      }
    } catch (e) {
      const err = (e && typeof e === "object" && "kind" in e)
        ? (e as AudioError)
        : { kind: "download-failed" as const, message: String(e) }
      console.error("[useCellAudio]", err)
      setError(err)
      setState("error")
    }
  }, [load])

  const pause = useCallback(() => {
    audioRef.current?.pause()
  }, [])

  return { state, error, isPlaying, play, pause }

export function AudioWaveform({ stream, height = 48, windowSec = 8, className }: Props) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const ctxRef = useRef<AudioContext | null>(null)
  const rafRef = useRef<number | null>(null)

  useEffect(() => {
    if (!stream) {
      const canvas = canvasRef.current
      if (canvas) {
        const ctx = canvas.getContext("2d")
        ctx?.clearRect(0, 0, canvas.width, canvas.height)
      }
      return
    }

    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return

    const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    const audioCtx = new AudioCtx()
    ctxRef.current = audioCtx
    const source = audioCtx.createMediaStreamSource(stream)
    const analyser = audioCtx.createAnalyser()
    analyser.fftSize = 1024
    analyser.smoothingTimeConstant = 0.3
    source.connect(analyser)

    const timeData = new Uint8Array(analyser.fftSize)
    // One RMS sample per frame; a rolling buffer sized to cover windowSec at
    // ~60fps. Using a Float32Array keeps the update O(1) via modular index.
    const bufferLen = Math.max(120, Math.floor(60 * windowSec))
    const amps = new Float32Array(bufferLen)
    let writeIdx = 0
    let frameCount = 0

    function resizeCanvas() {
      if (!canvas) return
      const dpr = window.devicePixelRatio || 1
      const cssWidth = canvas.clientWidth || 200
      canvas.width = Math.max(1, Math.floor(cssWidth * dpr))
      canvas.height = Math.max(1, Math.floor(height * dpr))
      ctx!.setTransform(dpr, 0, 0, dpr, 0, 0)
    }

    resizeCanvas()
    const ro = new ResizeObserver(resizeCanvas)
    ro.observe(canvas)

    function draw() {
      analyser.getByteTimeDomainData(timeData)
      // RMS amplitude for this frame, normalized to [0, 1].
      let sumSq = 0
      for (let i = 0; i < timeData.length; i++) {
        const v = (timeData[i] - 128) / 128
        sumSq += v * v
      }
      const rms = Math.sqrt(sumSq / timeData.length)
      amps[writeIdx] = rms
      writeIdx = (writeIdx + 1) % bufferLen
      frameCount++

      if (!canvas || !ctx) return
      const w = canvas.clientWidth || 200
      const h = height
      ctx.clearRect(0, 0, w, h)
      ctx.fillStyle = "rgba(239,68,68,0.08)" // red-500/8 subtle background
      ctx.fillRect(0, 0, w, h)
      const mid = h / 2
      ctx.strokeStyle = "rgb(239,68,68)"
      ctx.lineWidth = 1
      ctx.beginPath()
      for (let x = 0; x < w; x++) {
        // Map x → index in circular buffer. Older samples on the left, latest
        // on the right.
        const bufIdx = (writeIdx + bufferLen - Math.floor((w - x) / w * bufferLen)) % bufferLen
        const amp = amps[bufIdx] ?? 0
        const y = mid - amp * mid * 2.4 // scale up so quiet speech is visible
        const y2 = mid + amp * mid * 2.4
        if (x === 0) ctx.moveTo(x, y)
        else ctx.lineTo(x, y)
        ctx.lineTo(x, y2)
      }
      ctx.stroke()

      rafRef.current = requestAnimationFrame(draw)
    }

    rafRef.current = requestAnimationFrame(draw)

    return () => {

self.addEventListener("message", async (event: MessageEvent<IncomingMessage>) => {
  const msg = event.data
  if (msg.type !== "transcribe") return

  try {
    const pipe = await getPipe(msg.model ?? DEFAULT_MODEL, msg.requestId)
    // transformers.js wants Float32 mono PCM (it auto-resamples internally if
    // needed, but pre-resampling on the main thread saves CPU).
    const result = await pipe(msg.pcm as unknown as Float32Array, {
      return_timestamps: "word",
      language: msg.language,
      chunk_length_s: 30,
      stride_length_s: 5,
    })
    const r = (Array.isArray(result) ? result[0] : result) as {
      text: string
      chunks?: Array<{ text: string; timestamp: [number | null, number | null] }>
    }
    const chunks = (r.chunks ?? [])
      .filter((c) => c.timestamp[0] != null && c.timestamp[1] != null)
      .map((c) => ({ text: c.text.trim(), start: c.timestamp[0]!, end: c.timestamp[1]! }))
      .filter((c) => c.text.length > 0)
    const out: ResultMessage = {
      type: "result",
      requestId: msg.requestId,
      text: r.text,
      chunks,
    }
    ;(self as unknown as Worker).postMessage(out)
  } catch (e) {
    const out: ErrorMessage = {
      type: "error",
      requestId: msg.requestId,
      message: e instanceof Error ? e.message : String(e),
    }
    ;(self as unknown as Worker).postMessage(out)
  }
})

export type { OutgoingMessage, IncomingMessage, TranscribeRequest, ProgressMessage, ResultMessage, ErrorMessage }

export async function transcribeAudio(
  bytes: Uint8Array,
  opts: TranscriptionOptions = {},
): Promise<TranscriptionResult> {
  const pcm = await audioBytesToWhisperPcm(bytes)
  const worker = await getWorker()
  const requestId = `t-${++workerSeq}`

  const result = await new Promise<ResultMessage>((resolve, reject) => {
    const onMessage = (event: MessageEvent<ResultMessage | ErrorMessage | ProgressMessage>) => {
      const msg = event.data
      if (msg.requestId !== requestId) return
      if (msg.type === "progress") {
        opts.onProgress?.({
          status: msg.status, file: msg.file, loaded: msg.loaded, total: msg.total,
        })
        return
      }
      worker.removeEventListener("message", onMessage)
      if (msg.type === "result") resolve(msg)
      else reject(new Error(msg.message))
    }
    worker.addEventListener("message", onMessage)
    const req: TranscribeRequest = {
      type: "transcribe",
      requestId,
      pcm,
      sampleRate: WHISPER_SAMPLE_RATE,
      language: opts.language,
      model: opts.model,
    }
    worker.postMessage(req)
  })

  const timings = alignChunks(result.chunks, opts.cellText)
  return { text: result.text, chunks: result.chunks, timings }

export async function synthAndAttachAudio(args: SynthAndAttachArgs): Promise<{ audioId: string }> {
  const text = args.cellText.trim()
  if (!text) throw new Error("Cell has no text to synthesize")

  const blob = await synthesizeToWavBlob(text, {
    voice: args.voice,
    speed: args.speed,
    onProgress: args.onTtsProgress,
  })

  const audioId = buildAudioId(args.cellId)
  const result = await uploadCellAudio({
    session: args.session,
    projectId: args.projectId,
    audioId,
    ext: "wav",
    blob,
  })

  attachAudioToCell(args.doc, args.cellId, {
    audioId: result.audioId,
    url: result.url,
    username: args.username,
    mimeType: "audio/wav",
  })

  // Auto-transcribe so karaoke lights up immediately. Errors here are
  // non-fatal — the audio is already attached and playable.
  void (async () => {
    setTranscribeStatus(result.audioId, { kind: "loading", loaded: 0, total: 0, file: "" })
    const startedAt = Date.now()
    try {
      const audioBytes = new Uint8Array(await blob.arrayBuffer())
      const out = await transcribeAndStoreTimings(args.doc, args.cellId, result.audioId, audioBytes, {
        cellText: text,
        onProgress: (p) => {
          setTranscribeStatus(result.audioId, { kind: "loading", loaded: p.loaded, total: p.total, file: p.file })
          if (p.status === "ready" || (p.total > 0 && p.loaded >= p.total)) {
            setTranscribeStatus(result.audioId, { kind: "transcribing" })
          }
        },
      })
      setTranscribeStatus(result.audioId, {
        kind: "done", wordCount: out.timings.length, durationMs: Date.now() - startedAt,
      })
    } catch (e) {
      setTranscribeStatus(result.audioId, {
        kind: "error", message: e instanceof Error ? e.message : String(e),
      })
    }
  })()

  return { audioId: result.audioId }

export function requestAiModelConsent(model: AiModelInfo): Promise<boolean> {
  if (hasStoredConsent(model.id)) return Promise.resolve(true)
  if (pending) {
    // Coalesce concurrent requests for the same model — a single dialog
    // serves them all. Different models queue.
    if (pending.model.id === model.id) {
      const existing = pending
      return new Promise<boolean>((resolve) => {
        const prev = existing.resolve
        existing.resolve = (granted) => { prev(granted); resolve(granted) }
      })
    }
  }
  return new Promise<boolean>((resolve) => {
    pending = {
      model,
      resolve: (granted) => {
        if (granted) storeConsent(model.id)
        pending = null
        notify()
        resolve(granted)
      },
    }
    notify()
  })

export async function prefetchAiModels(opts: PrefetchOptions = {}): Promise<void> {
  const models = opts.models ?? ["whisper", "kokoro"]
  const promises: Promise<void>[] = []
  if (models.includes("whisper")) promises.push(warmWhisper())
  if (models.includes("kokoro")) promises.push(warmKokoro())
  await Promise.all(promises)

export interface ActiveAudioController {
  /** Returns true if audio is currently playing. Reads live, not a snapshot. */
  isPlaying: () => boolean
  play: () => Promise<void>
  pause: () => void
}

let current: ActiveAudioController | null = null
const listeners = new Set<() => void>()

function notify() { for (const l of listeners) l() }

export function setActiveAudio(controller: ActiveAudioController): void {
  if (current === controller) return
  current = controller
  notify()
}

export function clearActiveAudioIf(controller: ActiveAudioController): void {
  if (current === controller) {
    current = null
